    /// Regression test for the reverted `unregister_native_thread` monitor
    /// release: a thread that dies while blocked inside a native call made
    /// from within a `synchronized` region never executes its `monitorexit`
    /// bytecode. Without `release_monitors_held_by` in the unregister path,
    /// the monitor stays owned by the dead thread forever and every future
    /// `monitorenter` on that object blocks indefinitely.
    #[test]
    fn unregister_native_thread_releases_monitors_held_by_the_dying_thread() {
        let shared = test_shared();
        let mut thread = JvmThread::new(ThreadId(0), "test");
        let obj = shared.mem.heap.alloc_object(ClassId::new(0), 0);
        let native_tid = {
            let mut ctx = NativeContextImpl {
                shared: &shared,
                thread: &mut thread,
            };
            ctx.register_native_thread("dying-native-thread", true, 0)
        };
        // The native thread enters a monitor (simulating `synchronized (obj)
        // { blockingNativeCall(); }`) and then dies without ever calling
        // monitorexit. `release_monitors_held_by` only scans INFLATED
        // monitors (a thin-locked, uncontended object isn't tracked there),
        // so force inflation the same way a real blocked-in-native-call
        // thread would have -- `enter()`'s plain thin-lock fast path would
        // never exercise the code this test targets.
        let (_monitor, contended) = shared
            .threads
            .monitors
            .enter_inflated_or_contend(obj, ThreadId(native_tid))
            .expect("inflate");
        assert!(!contended, "fresh monitor should be acquired immediately");
        assert!(shared.threads.monitors.holds(obj, ThreadId(native_tid)));
        {
            let mut ctx = NativeContextImpl {
                shared: &shared,
                thread: &mut thread,
            };
            ctx.unregister_native_thread(native_tid);
        }
        assert!(
            !shared.threads.monitors.holds(obj, ThreadId(native_tid)),
            "a dead thread must not still be recorded as holding the monitor"
        );
        // A different thread must now be able to acquire the same object's
        // monitor without blocking.
        let other_tid = ThreadId(native_tid + 1);
        shared.threads.monitors.enter(obj, other_tid);
        assert!(shared.threads.monitors.holds(obj, other_tid));
        assert!(shared.threads.monitors.exit(obj, other_tid).is_ok());
    }

    /// The THIN-lock half of the same hang (`16eaae90c`), whose call site in
    /// `monitor_enter_blocking` a 2026-07-20 merge (`27aa91068`) dropped: a
    /// thread that dies holding a never-contended thin lock is invisible to the
    /// death-time sweep, and the next contender inflates the lock with the dead
    /// owner seeded in. `release_dead_thin_owner` must free exactly that case
    /// and nothing else — not a live owner, not an owner id the registry never
    /// registered, and not a dead thread's monitor that was inflated BEFORE it
    /// was acquired (the thread-termination handshake's shape).
    ///
    /// Driven through `enter_or_contend` + `release_dead_thin_owner` rather than
    /// `monitor_enter_blocking`, so a regression fails instead of parking the
    /// test thread forever.
    #[test]
    fn a_dead_threads_thin_lock_is_released_at_the_next_contention_point() {
        let shared = test_shared();
        let registry = &shared.threads.thread_registry;
        let monitors = &shared.threads.monitors;
        let contender = registry.next_thread_id();
        registry.register(contender, "contender", None);

        // Dead owner of a thin lock: released.
        let dead = registry.next_thread_id();
        registry.register(dead, "dies-holding-a-thin-lock", None);
        let obj = shared.mem.heap.alloc_object(ClassId::new(0), 0);
        monitors.enter(obj, dead);
        registry.mark_dead(dead);
        monitors.release_monitors_held_by(dead);
        assert!(
            monitors.holds(obj, dead),
            "the sweep cannot see a thin lock"
        );
        let m = monitors
            .enter_or_contend(obj, contender)
            .expect("held by the dead thread");
        release_dead_thin_owner(&shared, &m, contender);
        assert!(!monitors.holds(obj, dead));
        assert!(monitors.enter_or_contend(obj, contender).is_none());
        assert!(monitors.exit(obj, contender).is_ok());

        // Live owner of a thin lock: untouched.
        let live = registry.next_thread_id();
        registry.register(live, "alive", None);
        let obj2 = shared.mem.heap.alloc_object(ClassId::new(0), 0);
        monitors.enter(obj2, live);
        let m2 = monitors.enter_or_contend(obj2, contender).expect("held");
        release_dead_thin_owner(&shared, &m2, contender);
        assert!(monitors.holds(obj2, live));
        assert!(monitors.exit(obj2, live).is_ok());

        // An owner id the registry never registered: not evidence of death.
        let stranger = ThreadId(u64::from(u32::MAX));
        let obj3 = shared.mem.heap.alloc_object(ClassId::new(0), 0);
        monitors.enter(obj3, stranger);
        let m3 = monitors.enter_or_contend(obj3, contender).expect("held");
        release_dead_thin_owner(&shared, &m3, contender);
        assert!(monitors.holds(obj3, stranger));
        assert!(monitors.exit(obj3, stranger).is_ok());

        // Inflated first, then acquired, then the owner dies (the termination
        // handshake holds its mirror monitor exactly like this across
        // `mark_dead`): not this path's to release.
        let dying = registry.next_thread_id();
        registry.register(dying, "terminating", None);
        let obj4 = shared.mem.heap.alloc_object(ClassId::new(0), 0);
        let (_m4, contended) = monitors
            .enter_inflated_or_contend(obj4, dying)
            .expect("inflate");
        assert!(!contended);
        registry.mark_dead(dying);
        let m4 = monitors.enter_or_contend(obj4, contender).expect("held");
        release_dead_thin_owner(&shared, &m4, contender);
        assert!(monitors.holds(obj4, dying));
        assert!(monitors.exit(obj4, dying).is_ok());
    }

