    /// Round 14 wave 1 (lane compat), `CRATONVM_NATIVE_CREATE_STRING_HIT_OR_FRESH`
    /// (default ON): `create_string` answers a pool hit or a fresh String it
    /// does not insert; `intern_string` inserts. The first assertion fails on
    /// the old body, which inserted every miss.
    #[test]
    fn r14_compat_create_string_is_pool_hit_or_fresh() {
        let shared = test_shared();
        let mut thread = JvmThread::new(ThreadId(0), "test");
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        let a = ctx.create_string("r14-compat-computed");
        assert!(
            !shared.mem.string_pool.read().contains_key("r14-compat-computed"),
            "a create_string miss must not grow the pool"
        );
        let b = ctx.create_string("r14-compat-computed");
        assert_ne!(a.as_ptr(), b.as_ptr(), "two misses are two fresh Strings");
        let pooled = ctx.intern_string("r14-compat-computed");
        assert!(shared.mem.string_pool.read().contains_key("r14-compat-computed"));
        let hit = ctx.create_string("r14-compat-computed");
        assert_eq!(pooled.as_ptr(), hit.as_ptr(), "a pool hit answers the pooled String");
        assert_eq!(ctx.read_string(hit).as_deref(), Some("r14-compat-computed"));
    }

